'use strict';

// MODULES //

var tape = require( 'tape' );
var DebugStream = require( '@stdlib/streams/node/debug' );
var repl = require( './fixtures/repl.js' );


// FUNCTIONS //

/**
* Returns default settings.
*
* @private
* @returns {Object} default settings
*/
function defaultSettings() {
	return {
		'autoDeletePairs': false,
		'autoClosePairs': false,
		'completionPreviews': false,
		'syntaxHighlighting': false,
		'eagerEvaluation': false,
		'autoPage': false
	};
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof repl, 'function', 'main export is a function' );
	t.end();
});

tape( 'a REPL instance supports multiline continuous backspaces into the previous line', function test( t ) {
	var istream;
	var opts;
	var r;

	istream = new DebugStream({
		'name': 'repl-input-stream'
	});
	opts = {
		'input': istream,
		'settings': defaultSettings(),
		'tty': {
			'rows': 100,
			'columns': 80
		}
	};
	r = repl( opts, onClose );

	// Enter an incomplete expression that triggers multi-line input:
	istream.write( 'function foo() {' );
	istream.write( '\r' );

	t.strictEqual( r._multilineHandler.lineIndex(), 1, 'cursor is on line 1' );
	t.strictEqual( r._multilineHandler._lines.length, 2, 'two lines present' );

	// Backspace at the beginning of line 1:
	istream.write( '\u0008' );

	t.strictEqual( r._multilineHandler.lineIndex(), 0, 'cursor moves back to line 0' );
	t.strictEqual( r._multilineHandler._lines.length, 1, 'lines merged into line 0' );
	t.strictEqual( r._rli.line, 'function foo() {', 'line content matches' );

	// Close the input stream:
	istream.end();
	r.close();

	function onClose( error ) {
		if ( error ) {
			t.fail( error.message );
			return;
		}
		t.end();
	}
});

tape( 'a REPL instance supports moving to the previous line using left arrow in multiline mode', function test( t ) {
	var istream;
	var opts;
	var r;

	istream = new DebugStream({
		'name': 'repl-input-stream'
	});
	opts = {
		'input': istream,
		'settings': defaultSettings(),
		'tty': {
			'rows': 100,
			'columns': 80
		}
	};
	r = repl( opts, onClose );

	// Enter multi-line input:
	istream.write( 'function foo() {' );
	istream.write( '\r' );

	t.strictEqual( r._multilineHandler.lineIndex(), 1, 'cursor is on line 1' );

	// Press left arrow at the beginning of line 1:
	istream.write( '\u001b[1D' );

	t.strictEqual( r._multilineHandler.lineIndex(), 0, 'cursor moves back to line 0' );
	t.strictEqual( r._rli.cursor, 16, 'cursor is at end of line 0' );

	istream.end();
	r.close();

	function onClose( error ) {
		if ( error ) {
			t.fail( error.message );
			return;
		}
		t.end();
	}
});

tape( 'a REPL instance supports moving to the next line using right arrow in multiline mode', function test( t ) {
	var istream;
	var opts;
	var r;

	istream = new DebugStream({
		'name': 'repl-input-stream'
	});
	opts = {
		'input': istream,
		'settings': defaultSettings(),
		'tty': {
			'rows': 100,
			'columns': 80
		}
	};
	r = repl( opts, onClose );

	// Enter multi-line input:
	istream.write( 'function foo() {' );
	istream.write( '\r' );
	istream.write( 'var x = 1;' );

	// Move cursor up to line 0:
	istream.write( '\u001b[1A' );
	t.strictEqual( r._multilineHandler.lineIndex(), 0, 'cursor is on line 0' );

	// Move cursor to the end of line 0:
	r._rli.cursor = r._rli.line.length;

	// Press right arrow at the end of line 0:
	istream.write( '\u001b[1C' );

	t.strictEqual( r._multilineHandler.lineIndex(), 1, 'cursor moves to line 1' );
	t.strictEqual( r._rli.cursor, 0, 'cursor is at start of line 1' );

	istream.end();
	r.close();

	function onClose( error ) {
		if ( error ) {
			t.fail( error.message );
			return;
		}
		t.end();
	}
});

tape( 'a REPL instance supports custom keybinding aliases for multiline backspace (ctrl+h)', function test( t ) {
	var istream;
	var opts;
	var r;

	istream = new DebugStream({
		'name': 'repl-input-stream'
	});
	opts = {
		'input': istream,
		'settings': defaultSettings(),
		'tty': {
			'rows': 100,
			'columns': 80
		}
	};
	r = repl( opts, onClose );

	// Enter multi-line input:
	istream.write( 'function foo() {' );
	istream.write( '\r' );

	t.strictEqual( r._multilineHandler.lineIndex(), 1, 'cursor is on line 1' );

	// Press ctrl+h (ASCII 8) at the start of line 1:
	istream.write( '\x08' );

	t.strictEqual( r._multilineHandler.lineIndex(), 0, 'cursor moves back to line 0' );
	t.strictEqual( r._multilineHandler._lines.length, 1, 'lines merged into line 0' );

	istream.end();
	r.close();

	function onClose( error ) {
		if ( error ) {
			t.fail( error.message );
			return;
		}
		t.end();
	}
});
